// Issue #1341: every row of tests/fixtures/i18n_conformance.json rendered through the real dashboard runtime
// (frontend/i18n.js via CAI18N.tw) must equal "expected" (generated by FormatJS + Intl in
// tools/i18n_conformance_gen.mjs). Python renders the same rows (tests/test_i18n_conformance.py), so the two
// runtimes cannot drift. Usage: node tests/i18n_conformance.mjs [fixture.json]
//
// Row shapes: {lang, msg|key, params, catalogs?, strict?, expected}; see the header of the generator. Params may hold
// {"$f": "nan"|"inf"|"-inf"} float literals (JSON has no NaN), revived below.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { loadRuntime } from './i18n_node_shim.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const fixturePath = process.argv[2] || path.join(HERE, 'fixtures', 'i18n_conformance.json');
if (!fs.existsSync(fixturePath)) {
  console.error('i18n conformance: fixture not found: ' + fixturePath);
  process.exit(1);
}
const raw = JSON.parse(fs.readFileSync(fixturePath, 'utf8'));
const rows = Array.isArray(raw) ? raw : raw.rows;
if (!Array.isArray(rows) || rows.length === 0) {
  console.error('i18n conformance: fixture has no rows');
  process.exit(1);
}

// The expected values embed this ICU's CLDR data (separators, list patterns, day periods): a different ICU
// can legitimately print different text, so say so instead of reporting hundreds of confusing row diffs.
const wantIcu = !Array.isArray(raw) && raw.header && raw.header.icu;
if (wantIcu && process.versions.icu !== wantIcu) {
  console.error(`i18n conformance: this Node has ICU ${process.versions.icu} (Node ${process.version}) but the fixture was ` +
    `generated with ICU ${wantIcu} (Node ${raw.header.node}). Run it with the same Node (CI pins 22.12.0) or regenerate ` +
    'the fixture with tools/i18n_conformance_gen.mjs after reviewing the diff.');
  process.exit(1);
}

const FLOATS = { nan: NaN, inf: Infinity, '-inf': -Infinity };
function revive(v) {
  if (Array.isArray(v)) return v.map(revive);
  if (v && typeof v === 'object') {
    if ('$f' in v) return FLOATS[v.$f];
    return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, revive(x)]));
  }
  return v;
}

const { CAI18N } = loadRuntime({});
const KEY = 'conformance.row';
let bad = 0;
for (const [i, row] of rows.entries()) {
  CAI18N._test.reset();
  const cats = {};
  for (const [l, m] of Object.entries(row.catalogs || {})) cats[l] = { ...m };
  if (row.msg !== undefined) cats[row.lang] = { ...(cats[row.lang] || {}), [KEY]: row.msg };
  for (const [l, m] of Object.entries(cats)) CAI18N._test.setCatalog(l, m);
  CAI18N._test.setLang(row.lang);
  let got;
  try {
    got = CAI18N.tw({ key: row.key === undefined ? KEY : row.key, params: revive(row.params || {}) });
  } catch (e) {
    got = 'THROW ' + e.message;
  }
  if (got !== row.expected) {
    bad++;
    if (bad <= 25) {
      console.error(`row ${i} [${row.lang}] ${JSON.stringify(row.msg || row.key)} ${JSON.stringify(row.params)}\n  expected ${JSON.stringify(row.expected)}\n  got      ${JSON.stringify(got)}`);
    }
  }
}
if (bad) {
  console.error(`i18n conformance: ${bad} of ${rows.length} rows differ`);
  process.exit(1);
}
console.log(`i18n conformance: ${rows.length} rows OK`);
